async ({ workspace: { read, edit }, shell: { exec } }) => {
  const f: any = await read("src/thread.test.ts", { format: "raw" });
  const old = f.content.match(/\t\t\tprepare: async \(bytes: Uint8Array, mimeType: string\) => \{[\s\S]*?\n\t\t\t\},\n/)[0];
  const neu = "\t\t\tprepare: async (_bytes: Uint8Array, mimeType: string) => {\n\t\t\t\tprepared.push(mimeType);\n\t\t\t\treturn { data: \"Zml0dGVk\", mimeType: \"image/png\" };\n\t\t\t},\n";
  await edit("src/thread.test.ts", { revision: f.revision, changes: [{ kind: "replaceFile", content: f.content.replace(old, neu) }] });
  const r = await exec("npm run fix >/dev/null 2>&1; npm run check 2>&1", { timeoutMs: 300000, maxLines: 60, truncate: "tail" });
  return { code: r.code, out: r.stdout.split("\n").filter((l) => !/✓/.test(l)).slice(-40).join("\n") };
}
